operation EncodeDataDemo () : Unit {
    let sample = [DrawRandomDouble(0.0, 1.0), DrawRandomDouble(0.0, 1.0)];
    Message($"Raw data: {sample}");

    let norm = Sqrt(sample[0] ^ 2.0 + sample[1] ^ 2.0);
